@'
import fs from "fs"; import zlib from "zlib"; import path from "path"; import os from "os";
const TZ=8*3600*1000;
const dayEnd=Date.now();
const dayStart=dayEnd-8*864e5;
const base=path.join(os.homedir(),".dsh","sessions");
const ZSTD=Buffer.from([0x28,0xb5,0x2f,0xfd]);
function dec(buf){const idxs=[]; for(let i=0;(i=buf.indexOf(ZSTD,i))>=0;i+=4) idxs.push(i); if(idxs.length<=1){try{return zlib.zstdDecompressSync(buf).toString("utf8")}catch{return buf.toString("utf8")}} let out=""; for(let k=0;k<idxs.length;k++){const s=idxs[k],e=k+1<idxs.length?idxs[k+1]:buf.length; try{out+=zlib.zstdDecompressSync(buf.subarray(s,e)).toString("utf8")}catch{}} return out;}
const files=[];
(function walk(p){for(const e of fs.readdirSync(p,{withFileTypes:true})){const fp=path.join(p,e.name); if(e.isDirectory()) walk(fp); else if(/\.jsonl\.zstd$/.test(e.name)){const st=fs.statSync(fp); if(st.mtimeMs>=dayStart) files.push(fp);}}})(base);
const cats={};
const samples=[];
let calls=0, toolErr=0, exitNonZero=0, exitZeroNoise=0, ok=0;
function bump(k){cats[k]=(cats[k]||0)+1}
function clip(s){return String(s||"").replace(/\s+/g," ").slice(0,180)}
for(const fp of files){
  let ev; try{ev=dec(fs.readFileSync(fp)).split("\n").filter(Boolean).map(l=>{try{return JSON.parse(l)}catch{return null}}).filter(Boolean)}catch{continue}
  const nameBy={};
  for(const c of ev){ if(c.type==="tool/call" && c.data && c.data.name==="pwsh"){ nameBy[c.data.callId]=c.data; calls++; } }
  for(const tr of ev){
    if(tr.type!=="tool/result") continue;
    const id=tr.data && tr.data.message && tr.data.message.toolCallId;
    if(!nameBy[id]) continue;
    const err=tr.data && tr.data.error;
    const msg=tr.data && tr.data.message;
    const text=typeof msg==="string"?msg: JSON.stringify(msg||"").slice(0,4000);
    if(err){ toolErr++; const code=String(err.code||err.name||"OTHER"); bump("tool:"+code); if(samples.length<12) samples.push({k:code, t:clip(err.message||text)}); continue; }
    const body=text;
    if(/\[exit code: (?!0\])/.test(body) || /exit code: [1-9]/.test(body)){
      exitNonZero++;
      let k="exit:other";
      if(/NativeCommandError/.test(body)) k="exit:NativeCommandError";
      else if(/ParserError|TerminatorExpected/.test(body)) k="exit:ParserError";
      else if(/CommandNotFoundException/.test(body)) k="exit:CommandNotFound";
      else if(/FullyQualifiedErrorId/.test(body)) k="exit:PSErrorRecord";
      else if(/sandbox: file access denied/.test(body)) k="exit:sandbox";
      bump(k);
      if(samples.filter(s=>s.k.startsWith("exit")).length<10) samples.push({k, t:clip(body)});
    } else if(/NativeCommandError/.test(body)){
      exitZeroNoise++; bump("stderr-noise:NativeCommandError");
    } else ok++;
  }
}
console.log(JSON.stringify({files:files.length, calls, toolErr, exitNonZero, exitZeroNoise, ok, cats, samples}, null, 2));
'@ | Set-Content -Encoding utf8 "$env:TEMP\pwsh-fail-scan.mjs"; node "$env:TEMP\pwsh-fail-scan.mjs"

